-- Demo company fake data — Maintenance
-- Generated for demo/sales purposes. Run in the Supabase SQL editor.
-- Stock items/purchases/issues across all 3 locations, 3 recurring job
-- templates per location, a mix of completed jobs, two deliberately
-- overdue jobs per location, and a couple of upcoming/in-progress jobs.


















-- Verification:
select 'maint_items' as t, count(*) from maint_items where company_id = (select id from companies where slug='demo')
union all select 'maint_jobs', count(*) from maint_jobs where company_id = (select id from companies where slug='demo');
